// Regenerates lib/new-attractions/generated.ts (imports of every data file) and lib/new-attractions/day-trips.ts (the slugs of
// day-trip destinations, kept in a tiny file so client code never imports the content). Run after adding a data file:
//   node scripts/gen-new-attractions.mjs
// tests/new-attractions.test.ts fails when the generated files are out of date.
import { readdirSync, readFileSync, writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";

const root = path.resolve(new URL("..", import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, "$1"));
const dataDir = path.join(root, "lib", "new-attractions", "data");
mkdirSync(dataDir, { recursive: true });
const files = readdirSync(dataDir).filter((f) => f.endsWith(".json")).sort();
const batchFiles = files.filter((f) => /^batch-.*\.json$/.test(f));
const photoFiles = files.filter((f) => /^photos-.*\.json$/.test(f));
const ident = (f) => "d_" + f.replace(/\.json$/, "").replace(/[^a-zA-Z0-9]/g, "_");

let ts = "// GENERATED by scripts/gen-new-attractions.mjs: do not edit by hand.\n";
ts += 'import type { NewAttraction, NewPhoto } from "./types";\n';
for (const f of [...batchFiles, ...photoFiles]) ts += `import ${ident(f)} from "./data/${f}";\n`;
ts += `\nexport const batches: NewAttraction[][] = [${batchFiles.map((f) => `${ident(f)} as unknown as NewAttraction[]`).join(", ")}];\n`;
ts += `export const photoRegistries: Record<string, NewPhoto>[] = [${photoFiles.map((f) => `${ident(f)} as unknown as Record<string, NewPhoto>`).join(", ")}];\n`;
writeFileSync(path.join(root, "lib", "new-attractions", "generated.ts"), ts);

const dayTrips = batchFiles
  .flatMap((f) => JSON.parse(readFileSync(path.join(dataDir, f), "utf8")))
  .filter((d) => d.outsideBudapest)
  .map((d) => d.slug)
  .sort();
writeFileSync(
  path.join(root, "lib", "new-attractions", "day-trips.ts"),
  `// GENERATED by scripts/gen-new-attractions.mjs: do not edit by hand.\nexport const newDayTripSlugs: string[] = ${JSON.stringify(dayTrips)};\n`,
);
console.log(`generated: ${batchFiles.length} batch file(s), ${photoFiles.length} photo file(s), ${dayTrips.length} day-trip slug(s)`);
